"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useParams } from "react-router-dom";
import { CheckCircle, AlertCircle, Loader2, ArrowLeft, Plus, Trash2, Upload } from "lucide-react";
import Layout from "../../Layout";

export default function EditSortie() {
  const navigate = useNavigate();
  const { id } = useParams();
  const [formData, setFormData] = useState({
    date: "",
    bon: null,
    type: "Bon de sortie",
    products: [{ productId: "", quantity: "" }],
    chefName: "",
  });
  const [products, setProducts] = useState([]);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [previewImage, setPreviewImage] = useState(null);

  useEffect(() => {
    fetchSortieAndProducts();
  }, []);

  const fetchSortieAndProducts = async () => {
    setIsLoading(true);
    const token = localStorage.getItem("token");

    try {
      const [sortieRes, productsRes] = await Promise.all([
        axios.get(`${process.env.REACT_APP_API_URL}/api/sorties/${id}`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/products`, { headers: { Authorization: `Bearer ${token}` } }),
      ]);

      const sortie = sortieRes.data;
      setFormData({
        date: sortie.date.split("T")[0],
        bon: null,
        type: sortie.type || "Bon de sortie",
        products: sortie.products.map((p) => ({
          productId: p.productId._id,
          quantity: p.quantity,
        })),
        chefName: sortie.chefName || "",
      });
      setPreviewImage(sortie.bonId?.image ? `${process.env.REACT_APP_API_URL}${sortie.bonId.image}` : null);
      setProducts(productsRes.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la récupération des données");
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (e, index) => {
    const { name, value, files } = e.target;
    if (index === undefined) {
      if (name === "bon" && files?.length > 0) {
        setFormData({ ...formData, bon: files[0] });
        const reader = new FileReader();
        reader.onloadend = () => setPreviewImage(reader.result);
        reader.readAsDataURL(files[0]);
      } else {
        setFormData({ ...formData, [name]: value });
      }
    } else {
      const updatedProducts = [...formData.products];
      updatedProducts[index][name] = value;
      setFormData({ ...formData, products: updatedProducts });
    }
  };

  const addProduct = () => {
    setFormData({
      ...formData,
      products: [...formData.products, { productId: "", quantity: "" }],
    });
  };

  const removeProduct = (index) => {
    const updatedProducts = formData.products.filter((_, i) => i !== index);
    setFormData({ ...formData, products: updatedProducts });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setIsSubmitting(true);

    const token = localStorage.getItem("token");

    try {
      const formDataToSend = new FormData();
      formDataToSend.append("date", formData.date);
      formDataToSend.append("chefName", formData.chefName);
      if (formData.bon) {
        formDataToSend.append("bon", formData.bon);
      }

      const productsToSend = formData.products.map((product) => ({
        productId: product.productId,
        quantity: parseInt(product.quantity),
      }));

      formDataToSend.append("products", JSON.stringify(productsToSend));

      await axios.put(`${process.env.REACT_APP_API_URL}/api/sorties/${id}`, formDataToSend, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data",
        },
      });
      setSuccess("Sortie mise à jour avec succès !");
      setTimeout(() => navigate("/ManageSortie"), 2000);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la mise à jour de la sortie");
      console.error("Erreur Frontend:", err.response?.data || err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Layout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 py-8">
        <div className="mb-6">
          <button onClick={() => navigate("/ManageSortie")} className="flex items-center text-[#00717F] hover:text-[#C8A45D]">
            <ArrowLeft className="h-4 w-4 mr-1" /> Retour à la liste
          </button>
        </div>

        <div className="bg-white rounded-2xl shadow-xl overflow-hidden">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <h2 className="text-2xl font-bold tracking-tight">Modifier une Sortie</h2>
            <p className="text-white/80 mt-1 text-sm">Mettre à jour les détails de la sortie</p>
          </div>

          {(error || success) && (
            <div className={`m-6 p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${error ? "border-red-500" : "border-green-500"} rounded-r-lg flex items-center gap-3`}>
              {error ? <AlertCircle className="h-5 w-5 text-red-500" /> : <CheckCircle className="h-5 w-5 text-green-500" />}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>{error || success}</p>
            </div>
          )}

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                <p className="text-[#00717F] text-sm font-medium">Chargement des données...</p>
              </div>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="p-6">
              <div className="space-y-8">
                <div className="bg-[#F5F6FA]/50 p-6 rounded-xl border border-[#C8A45D/30]/50">
                  <h3 className="text-lg font-medium text-[#00717F] mb-4">Informations de la Sortie</h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
                      <input
                        type="date"
                        name="date"
                        value={formData.date}
                        onChange={handleChange}
                        className="w-full px-4 py-2.5 border border-gray-300 rounded-lg"
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Nom du Chef</label>
                      <input
                        type="text"
                        name="chefName"
                        value={formData.chefName}
                        onChange={handleChange}
                        className="w-full px-4 py-2.5 border border-gray-300 rounded-lg"
                        placeholder="Entrez le nom du chef"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Bon</label>
                      <div className="flex items-center justify-center w-full">
                        <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer bg-gray-50 hover:bg-gray-100">
                          <div className="flex flex-col items-center justify-center pt-5 pb-6">
                            {previewImage ? (
                              <img src={previewImage} alt="Aperçu" className="h-20 object-contain mb-2" />
                            ) : (
                              <>
                                <Upload className="w-8 h-8 mb-2 text-gray-500" />
                                <p className="text-sm text-gray-500">Cliquez ou glissez une image ici</p>
                              </>
                            )}
                          </div>
                          <input type="file" name="bon" accept="image/*" onChange={handleChange} className="hidden" />
                        </label>
                      </div>
                    </div>
                  </div>
                </div>

                {formData.products.map((product, index) => (
                  <div key={index} className="bg-[#F5F6FA]/50 p-6 rounded-xl border border-[#C8A45D/30]/50 relative">
                    <button
                      type="button"
                      onClick={() => removeProduct(index)}
                      className="absolute top-4 right-4 text-red-600 hover:text-red-800"
                      disabled={formData.products.length === 1}
                    >
                      <Trash2 className="h-5 w-5" />
                    </button>
                    <h3 className="text-lg font-medium text-[#00717F] mb-4">Produit {index + 1}</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Produit</label>
                        <select
                          name="productId"
                          value={product.productId}
                          onChange={(e) => handleChange(e, index)}
                          className="w-full px-4 py-2.5 border border-gray-300 rounded-lg"
                          required
                        >
                          <option value="">Sélectionner un produit</option>
                          {products.map((p) => (
                            <option key={p._id} value={p._id}>
                              {p.nameProduct} ({p.quantity} {p.unity === "unit" ? "unité" : p.unity})
                            </option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Quantité</label>
                        <input
                          type="number"
                          name="quantity"
                          value={product.quantity}
                          onChange={(e) => handleChange(e, index)}
                          className="w-full px-4 py-2.5 border border-gray-300 rounded-lg"
                          min="1"
                          required
                        />
                      </div>
                    </div>
                  </div>
                ))}
              </div>
              <div className="mt-6 flex justify-between">
                <button
                  type="button"
                  onClick={addProduct}
                  className="px-5 py-2.5 bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white rounded-lg hover:bg-[#C8A45D] flex items-center gap-2 font-medium"
                >
                  <Plus className="h-4 w-4" /> Ajouter un Produit
                </button>
                <div className="flex gap-4">
                  <button
                    type="button"
                    onClick={() => navigate("/ManageSortie")}
                    className="px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium"
                  >
                    Annuler
                  </button>
                  <button
                    type="submit"
                    disabled={isSubmitting}
                    className="px-5 py-2.5 bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white rounded-lg hover:opacity-90 font-medium flex items-center gap-2"
                  >
                    {isSubmitting ? (
                      <>
                        <Loader2 className="h-4 w-4 animate-spin" /> Traitement...
                      </>
                    ) : (
                      "Mettre à jour la Sortie"
                    )}
                  </button>
                </div>
              </div>
            </form>
          )}
        </div>
      </div>
    </Layout>
  );
}
